import numpy as np

def solve_optimal_c(n):
    max_ratio = 0
    # Let's try a broader range for c and more points
    for c in np.arange(-n, n + 0.5, 0.5):
        f = []
        for i in range(1, n+1):
            fi = (n-i) * (n+i-2*c)
            f.append(fi)

        is_concave = True
        for i in range(1, n-1):
            if f[i] - f[i-1] < f[i+1] - f[i]:
                is_concave = False
                break

        if is_concave and all(x >= -1e-9 for x in f):
            s = sum(x**2 for x in f)
            t = sum((i+1) * x**2 for i, x in enumerate(f))
            max_ratio = max(max_ratio, s/t)
    return max_ratio

for n in range(2, 15):
    print(f"n={n}, max_ratio={solve_optimal_c(n):.6f}")

